{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section 825.303 of Title 29 of the Code of Federal Regulations governs employee notice requirements for unforeseeable Family and Medical Leave Act (FMLA) leave."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "When the approximate timing of the need for FMLA leave is not foreseeable, an employee must provide notice to the employer as soon as practicable under the facts and circumstances of the particular case."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "It generally should be practicable for an employee to provide notice of unforeseeable leave within the time prescribed by the employer's usual and customary notice requirements applicable to such leave."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "Notice of unforeseeable leave may be given by the employee's spokesperson (such as a spouse, adult family member, or other responsible party) if the employee is unable to provide notice personally."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "exception",
      "meaning": "As an illustration of timing flexibility, an employee who takes their child to an emergency room for a severe asthma attack is not required to leave the child to report the absence while the child is receiving emergency treatment."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "As an illustration of prompt notice, if an employee's child experiences an asthma attack that requires only an inhaler at home followed by rest, the employee is expected to call the employer promptly after ensuring the child has used the inhaler."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employee must provide sufficient information for an employer to reasonably determine whether the FMLA may apply to the leave request."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "Depending on the situation, sufficient leave notice information may include: that a condition renders the employee unable to perform job functions; that the employee is pregnant or hospitalized overnight; whether the employee or family member is under continuing care of a health care provider; that a military member is on or called to covered active duty (or notified of an impending call/order), the leave is for a listed qualifying exigency reason, and the anticipated duration; or that a condition renders a family member unable to perform daily activities or the family member is a covered servicemember with a serious injury/illness, along with the anticipated duration if known."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "When an employee seeks leave for the first time for a FMLA-qualifying reason, the employee is not required to expressly assert rights under the FMLA or even mention the FMLA."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "When an employee seeks leave due to a qualifying reason for which the employer has previously provided the employee FMLA-protected leave, the employee must specifically reference either the qualifying reason for leave or the need for FMLA leave."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "threshold",
      "meaning": "Calling in 'sick' without providing additional information does not constitute sufficient notice to trigger an employer's obligations under the FMLA."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "recommendation",
      "meaning": "The employer is expected to obtain any additional required information regarding the leave request through informal means."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "An employee is obligated to respond to an employer's questions designed to determine whether an absence is potentially FMLA-qualifying."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "condition",
      "meaning": "An employee's failure to respond to reasonable employer inquiries regarding a leave request may result in the denial of FMLA protection if the employer remains unable to determine whether the leave is FMLA-qualifying."
    },
    {
      "quote_ref": "F003:F004",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "When the need for leave is not foreseeable, an employee must comply with the employer's usual and customary notice and procedural requirements for requesting leave, absent unusual circumstances."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F003:F004"],
      "kind": "permission",
      "meaning": "An employer may, as part of its usual notice and procedural requirements, require employees to call a designated number or a specific individual to request leave."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F003:F004"],
      "kind": "exception",
      "meaning": "If an employee requires emergency medical treatment, the employee is not required to follow the employer's call-in procedure until the employee's condition is stabilized and the employee has access to, and is able to use, a phone."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F003:F004"],
      "kind": "exception",
      "meaning": "In the case of an emergency requiring leave for a FMLA-qualifying reason, written advance notice pursuant to an employer's internal rules and procedures may not be required when FMLA leave is involved."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F003:F004"],
      "kind": "condition",
      "meaning": "If an employee fails to comply with the employer's usual notice and procedural requirements for unforeseeable leave and no unusual circumstances justify that failure, the employee's FMLA-protected leave may be delayed or denied."
    }
  ]
}
